steps = [
    step("本机的 IGMP 设置:net.inet.igmp.default_version = 3(默认说 IGMPv3),v1enable = 1、v2enable = 1(也接受旧版本),sendra = 1(报文带 Router Alert 选项),sendlocal = 1(也报告 224.0.0.x 本地链路的组),gsrdelay = 10。netstat -s -p igmp 的累计:收到 IGMP 报文 84112 个,其中 V1/V2 成员查询 3497 个、成员报告 80613 个(大多是别的设备发的),本机发出的成员报告 1713 个。默认是 v3,但这个网段上看到的都是 v2 报文(见后面几节),说明会降级到对方的版本。", t=tl(S(1)), mark=lidx(S(1), 'net.inet.igmp.default_version', 'netstat -s -p igmp 累计'), done=lidx(S(1), 'net.inet.igmp.v1enable', 'net.inet.igmp.sendra', 'default_version = 3'), b=bars([['收到的 IGMP 报文', 84112, '84,112'], ['成员报告(多半是别的设备发的)', 80613, '80,613'], ['V1/V2 成员查询', 3497, '3,497'], ['本机发出的成员报告', 1713, '1,713']], 84112, mark=[1], done=[0, 2, 3]), kv=KV([['default_version', '3(IGMPv3)'], ['v1enable / v2enable', '都是 1'], ['sendra', '1:带 Router Alert'], ['累计', '收到 84,112 个,几乎全是别人的报告']], ['累计'])),
    step("加入组再离开,看线上的 IGMP 报文:加入 239.255.42.99 时本机只发出 1 个 IGMPv2 成员报告(0x16):IP 目的就是组地址 239.255.42.99,以太网目的 01:00:5e:7f:2a:63,TTL 1,IP 头 24 字节(含 Router Alert),IGMP 部分 8 字节,组地址 239.255.42.99,校验和正确。离开时发出 1 个 IGMPv2 离开报文(0x17):IP 目的是 224.0.0.2(所有路由器),以太网目的 01:00:5e:00:00:02,组地址仍是 239.255.42.99,校验和正确。IGMPv2 报文固定 8 字节:类型 1 + 最大响应时间 1(单位 0.1 秒)+ 校验和 2 + 组地址 4;校验和是对这 8 字节做的互联网校验和(第 17 篇)。", t=tl(S(2)), mark=lidx(S(2), 'IGMPv2 报告(0x16)', 'IGMPv2 离开(0x17)'), done=lidx(S(2), '加入后本机发出', '离开后本机发出', 'IGMPv2 报文固定'), b=bars([['IGMPv2 报文', 8, '8 字节'], ['IP 头(含 Router Alert)', 24, '24 字节']], 24, mark=[0], done=[1]), kv=KV([['加入', '1 个报告,发给组地址本身'], ['离开', '1 个 Leave,发给 224.0.0.2'], ['IGMP 部分', '8 字节:类型 · 响应时间 · 校验和 · 组'], ['IP 头', '24 字节:20 + Router Alert 4']], ['离开'])),
    step("被动听 180 秒(本机已经加入了两个组):没有抓到任何成员查询,本机也就没有发出任何报告。180 秒共抓到 79 个 IGMP 报文,全部是别的设备发的 IGMPv2 报告;netstat 累计的 V1/V2 成员查询在这段时间 +0,而成员报告 +79。累计里的 3497 个查询说明这个网段上以前出现过查询者,但至少这 180 秒里没有出现;查询的间隔和最大响应时间、本机怎么在 0 到最大响应时间之间随机延迟回应,因此没有在这次观察里看到。", t=tl(S(3)), mark=lidx(S(3), '180 秒里没有抓到任何成员查询', '本机发出 0 个'), done=lidx(S(3), '180 秒共抓到', 'netstat 累计的变化'), b=bars([['成员报告(别的设备)', 79, '79'], ['成员查询', 0, '0'], ['本机发出的报告', 0, '0']], 79, mark=[1, 2], done=[0]), kv=KV([['180 秒', '79 个报告 · 0 个查询'], ['本机', '没被查询,所以没发报告'], ['累计', '以前收到过 3497 个查询']], ['本机'])),
    step("别的设备发的 IGMP 报告:这 79 个 IGMPv2 报告来自 27 个不同的源地址,全部是同一个组 224.0.0.251(mDNS 的组);TTL 都是 1,IP 头都是 24 字节(带 Router Alert),79 个的校验和全部正确,最大响应时间字段恒为 0。每个报告的 IP 目的地址就是被报告的那个组(79 / 79),所以同一个组的其它成员也能听到。按报告抑制的设计,听到别人已经报告了同一个组,自己应该不再发;但这里 27 个设备在没有任何查询的情况下都各自发了报告,没有看到抑制的效果——这些设备为什么会主动、重复地发报告,没有查清。", t=tl(S(4)), mark=lidx(S(4), '79 个 IGMPv2 报告来自', '按组统计'), done=lidx(S(4), 'IGMPv2 报告的 IP 目的地址'), b=bars([['报告', 79, '79'], ['不同的源地址', 27, '27'], ['不同的组', 1, '1(224.0.0.251)']], 79, mark=[1], done=[0, 2]), kv=KV([['79 个报告', '27 个设备,全是 224.0.0.251'], ['校验和', '79 / 79 正确'], ['TTL / IP 头', '1 / 24 字节'], ['抑制', '没有看到:27 个设备都发了']], ['抑制'])),
]
